exercise.solution:
function jobStages(jobs) {
  const names = Object.keys(jobs);
  const nameSet = new Set(names);
  const dependencies = new Map();

  for (const name of names) {
    const needs = jobs[name]?.needs;
    const deps = needs === undefined
      ? []
      : Array.isArray(needs)
        ? [...needs]
        : [needs];

    for (const dependency of deps) {
      if (!nameSet.has(dependency)) {
        throw new Error(`unknown dependency: ${dependency}`);
      }
    }

    dependencies.set(name, new Set(deps));
  }

  const remaining = new Map();
  for (const [name, deps] of dependencies) {
    remaining.set(name, new Set(deps));
  }

  const stages = [];

  while (remaining.size > 0) {
    const ready = [...remaining.keys()]
      .filter((name) => remaining.get(name).size === 0)
      .sort();

    if (ready.length === 0) {
      throw new Error("cycle detected in job dependencies");
    }

    stages.push(ready);

    for (const name of ready) {
      remaining.delete(name);
    }

    for (const deps of remaining.values()) {
      for (const name of ready) {
        deps.delete(name);
      }
    }
  }

  return stages;
}

function expandMatrix(matrix) {
  const keys = Object.keys(matrix).filter((key) => key !== "include" && key !== "exclude");
  const combinations = [];

  function build(index, current) {
    if (index === keys.length) {
      combinations.push({ ...current });
      return;
    }

    const key = keys[index];
    for (const value of matrix[key]) {
      current[key] = value;
      build(index + 1, current);
    }
  }

  if (keys.length === 0) {
    combinations.push({});
  } else {
    build(0, {});
  }

  const excluded = combinations.filter((combo) => {
    return !(matrix.exclude ?? []).some((rule) => {
      return Object.keys(rule).every((key) => combo[key] === rule[key]);
    });
  });

  for (const include of matrix.include ?? []) {
    excluded.push({ ...include });
  }

  return excluded;
}

function shouldRun(trigger, event) {
  const config = trigger?.[event?.name];

  if (!config) {
    return false;
  }

  if (!Array.isArray(config.branches)) {
    return true;
  }

  return config.branches.some((pattern) => {
    if (pattern.endsWith("/*")) {
      const prefix = pattern.slice(0, -1);
      return typeof event.branch === "string" && event.branch.startsWith(prefix);
    }

    return event.branch === pattern;
  });
}

