const jobs = {
  package: { needs: ["backend", "frontend"] },
  frontend: {},
  backend: {}
};
return JSON.stringify(jobStages(jobs)) === JSON.stringify([["backend", "frontend"], ["package"]]);

const jobs = {
  deploy: { needs: "test" },
  test: {}
};
return JSON.stringify(jobStages(jobs)) === JSON.stringify([["test"], ["deploy"]]);

const jobs = {
  zebra: {},
  alpha: {},
  middle: {}
};
return JSON.stringify(jobStages(jobs)) === JSON.stringify([["alpha", "middle", "zebra"]]);

const jobs = {
  deploy: { needs: "package" },
  package: { needs: ["backend", "frontend"] },
  frontend: {},
  backend: {}
};
return JSON.stringify(jobStages(jobs)) === JSON.stringify([["backend", "frontend"], ["package"], ["deploy"]]);

const jobs = {
  build: { needs: "test" },
  test: { needs: "build" }
};
try {
  jobStages(jobs);
  return false;
} catch (error) {
  return String(error?.message).toLowerCase().includes("cycle");
}

const jobs = {
  deploy: { needs: "missing" }
};
try {
  jobStages(jobs);
  return false;
} catch (error) {
  return String(error?.message).toLowerCase().includes("unknown");
}

const jobs = {
  deploy: { needs: ["build"] },
  build: {}
};
const before = JSON.stringify(jobs);
jobStages(jobs);
return JSON.stringify(jobs) === before && Array.isArray(jobs.deploy.needs) && jobs.deploy.needs[0] === "build";

const result = expandMatrix({ java: [17, 21], os: ["ubuntu", "windows"] });
return JSON.stringify(result) === JSON.stringify([
  { java: 17, os: "ubuntu" },
  { java: 17, os: "windows" },
  { java: 21, os: "ubuntu" },
  { java: 21, os: "windows" }
]);

const result = expandMatrix({
  java: [17, 21],
  os: ["ubuntu", "windows"],
  exclude: [{ java: 17, os: "windows" }]
});
return JSON.stringify(result) === JSON.stringify([
  { java: 17, os: "ubuntu" },
  { java: 21, os: "ubuntu" },
  { java: 21, os: "windows" }
]);

const result = expandMatrix({
  java: [17],
  os: ["ubuntu"],
  include: [{ java: 21, os: "windows", experimental: true }]
});
return JSON.stringify(result) === JSON.stringify([
  { java: 17, os: "ubuntu" },
  { java: 21, os: "windows", experimental: true }
]) &&
  result.every((combo) => !("include" in combo) && !("exclude" in combo));

return shouldRun(
  { push: { branches: ["main", "release/*"] } },
  { name: "push", branch: "release/1.2" }
) === true &&
shouldRun(
  { push: { branches: ["main", "release/*"] } },
  { name: "push", branch: "feature/login" }
) === false &&
shouldRun(
  { push: { branches: ["main", "release/*"] } },
  { name: "push", branch: "main" }
) === true;
